export async function run(settings) {
  const deadline = Date.now() + settings.requestBudgetSeconds * 1000;
  for (let i = 0; i < settings.maxAttempts; i++) {
    if (i > 0) await sleep(settings.retryDelaysMs[i - 1], deadline);
    await attempt(settings.attemptTimeoutMs, deadline);
  }
}

